on conflict (municipality_id,indicator_code,reference_year,reference_period,source_id) do update set
 indicator_name=excluded.indicator_name,value=excluded.value,unit=excluded.unit,source_url=excluded.source_url,
 retrieved_at=now(),verification_status=excluded.verification_status,notes=excluded.notes,
 geographic_level=excluded.geographic_level,geographic_name=excluded.geographic_name,updated_at=now();

update public.data_sources set
 description='Муниципальный паспорт Когалыма за 2026 год: импортированы общий показатель среднесписочной численности работников и отраслевая разбивка по 16 секторам за январь–март; также имеются отдельные показатели заработной платы, отгрузки и торговли.',
 coverage='Когалым · официальный срез I квартала 2026 года; 16 отраслевых наблюдений плюс агрегаты по ряду показателей',
 notes='Среднесписочная численность и отраслевые значения относятся к обследуемым организациям без субъектов малого предпринимательства. Отраслевой список не следует считать полным покрытием всех видов деятельности без проверки остальных строк паспорта.',
 import_status='partially_imported',last_checked_at=now(),updated_at=now()
where id='rosstat_passport_kogalym';